{
  "findings": [
    {
      "check_id": "CKV2_AWS_22",
      "title": "Ensure an IAM User does not have access to the console",
      "resource": "aws_iam_user.privesc11-PutGroupPolicy-user",
      "severity": "MEDIUM",
      "explanation": "The IAM user 'privesc11-PutGroupPolicy-user' is created without explicitly disabling console access, potentially allowing it to access the AWS Management Console."
    }
  ],
  "patched_code": "resource \"aws_iam_user\" \"privesc11-PutGroupPolicy-user\" {\n  name          = \"privesc11-PutGroupPolicy-user\"\n  path          = \"/\"\n  force_destroy = true\n}\n\nresource \"aws_iam_user_login_profile\" \"privesc11-PutGroupPolicy-user\" {\n  count = 0\n  user = aws_iam_user.privesc11-PutGroupPolicy-user.name\n}\n",
  "fix_summary": "Added a count = 0 to an aws_iam_user_login_profile resource to ensure the IAM user does not have console access by default."
}
